import{_ as e,o as r,c as a,a2 as i}from"./chunks/framework.DZhUhjDB.js";const h=JSON.parse('{"title":"🎯 Penetration Tester (Especializado)","description":"🎯 Penetration Tester (Especializado)","frontmatter":{"title":"🎯 Penetration Tester (Especializado)","description":"🎯 Penetration Tester (Especializado)"},"headers":[],"relativePath":"roles/red-team/penetration-tester-specialized.md","filePath":"roles/red-team/penetration-tester-specialized.md","lastUpdated":1787529976000}'),d={name:"roles/red-team/penetration-tester-specialized.md"};function o(s,t,n,l,c,p){return r(),a("div",null,[...t[0]||(t[0]=[i(`<div align="center"><h1 id="🎯-penetration-tester-especializado" tabindex="-1">🎯 Penetration Tester (Especializado)</h1><p><strong>NIST NICE · Penetration Tester (Advanced)</strong></p><p><em>&quot;Cuando el OSCP ya no te impresiona y empiezas a buscar lo que rompe.&quot;</em></p><p><img src="https://img.shields.io/badge/tier%20salarial-A%2FS-purple" alt="Tier"> <img src="https://img.shields.io/badge/demanda-alta-green" alt="Demanda"> <img src="https://img.shields.io/badge/entry%20level-experto-critical" alt="Entry"></p></div><hr><h2 id="📋-descripcion" tabindex="-1">📋 Descripción</h2><p>Evolución del pentester generalista hacia un <strong>nicho profundo</strong>: web app exploitation avanzada, exploit development, red teaming con evasión, kernel/driver, mobile, ICS/OT, hardware o AppSec ofensivo. Aquí cada línea de código que escribes vale más — porque pocos lo entienden.</p><p>Distinción clave con <code>pentester-red-team</code> (rama generalista):</p><ul><li><strong>Generalista</strong>: cubre web + AD + cloud con metodología</li><li><strong>Especializado</strong>: domina <strong>un vertical</strong> a profundidad de bypass de mitigaciones (ASLR, DEP, CFG, AMSI, EDR userland hooks)</li></ul><hr><h2 id="👤-roles-tipicos" tabindex="-1">👤 Roles típicos</h2><ul><li><strong>Senior Web Application Pentester</strong> — OSWE-tier, white-box reviews</li><li><strong>Red Team Operator senior</strong> — OSEP, evasion + custom tooling</li><li><strong>Exploit Developer</strong> — OSED, 0-days, ROP/JOP, kernel</li><li><strong>Mobile Pentester</strong> — iOS/Android, jailbreak / root</li><li><strong>ICS/OT Pentester</strong> — protocolos industriales (combo con <code>seguridad-iot-ot</code>)</li><li><strong>Hardware Security Researcher</strong> — embedded, side-channel, JTAG</li><li><strong>Adversary Emulation Engineer</strong> <em>(big tech)</em> — purple-aligned</li></ul><hr><h2 id="🛠️-stack-y-herramientas" tabindex="-1">🛠️ Stack y herramientas</h2><table tabindex="0"><thead><tr><th>Categoría</th><th>Herramientas</th></tr></thead><tbody><tr><td><strong>Exploit dev</strong></td><td>Ghidra · IDA Pro · radare2 · x64dbg · WinDbg · pwntools · ROPgadget · pwndbg</td></tr><tr><td><strong>Web avanzado</strong></td><td>Burp Suite Pro · Caido · Param Miner · Logger++ · Autorize · custom Python</td></tr><tr><td><strong>AD avanzado</strong></td><td>Rubeus · BloodHound CE · Certipy · ADCS attack tools · NetExec · pyKRB5</td></tr><tr><td><strong>Evasion</strong></td><td>Donut · Sliver custom profiles · Mythic agents · Havoc · syscalls direct</td></tr><tr><td><strong>Mobile</strong></td><td>Frida · Objection · MobSF · Burp Mobile · Drozer · iLEAPP · Magisk</td></tr><tr><td><strong>Reverse / unpacking</strong></td><td>Ghidra · IDA + Hex-Rays · Binary Ninja · de4dot</td></tr><tr><td><strong>Fuzzing</strong></td><td>AFL++ · libFuzzer · honggfuzz · radamsa · BooFuzz (proto)</td></tr><tr><td><strong>Kernel</strong></td><td>WinDbg + symbols · LiveKD · IDA + decompilers · Volatility for crash dumps</td></tr><tr><td><strong>Hardware</strong></td><td>ChipWhisperer · JTAG · UART · Bus Pirate · Saleae · HackRF</td></tr></tbody></table><hr><h2 id="🎓-certificaciones-recomendadas" tabindex="-1">🎓 Certificaciones recomendadas</h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Certificación</th><th>Vendor</th><th>Costo (USD)</th><th>Notas</th></tr></thead><tbody><tr><td>Pre-req</td><td>OSCP</td><td>OffSec</td><td>~$1,649</td><td>Asumida</td></tr><tr><td>Mid</td><td>OSWE (Web)</td><td>OffSec</td><td>~$1,649</td><td>White-box web exploitation</td></tr><tr><td>Mid</td><td>OSEP (Evasion)</td><td>OffSec</td><td>~$1,649</td><td>Red team con bypass</td></tr><tr><td>Mid</td><td>OSED (Exploit Dev)</td><td>OffSec</td><td>~$1,649</td><td>Windows exploit dev</td></tr><tr><td>Mid</td><td>CRTO / CRTL</td><td>Zero-Point Sec</td><td>~$365-500</td><td>Cobalt Strike + C2 ops</td></tr><tr><td>Mid</td><td>OSMR / OSWP</td><td>OffSec</td><td>~$450-1,649</td><td>Mobile / Wi-Fi</td></tr><tr><td>Senior</td><td>OSCE3 (OSEP+OSWE+OSED)</td><td>OffSec</td><td>~$5,000</td><td>Trinity, top tier</td></tr><tr><td>Senior</td><td>OSEE</td><td>OffSec</td><td>~$3,000</td><td>Hardware/embedded</td></tr><tr><td>Senior</td><td>GIAC GXPN</td><td>SANS</td><td>~$2,500+</td><td>Exploit dev SANS</td></tr></tbody></table><hr><h2 id="🗺️-roadmap-12-meses-post-oscp" tabindex="-1">🗺️ Roadmap (12 meses, post-OSCP)</h2><h3 id="fase-1-—-elegir-nicho-0-2-meses" tabindex="-1">Fase 1 — Elegir nicho (0-2 meses)</h3><ul><li>[ ] Decidir vertical: web (OSWE) | red team (OSEP) | exploit dev (OSED) | mobile | ICS | hardware</li><li>[ ] Lectura central del nicho (e.g. <em>The Web App Hacker&#39;s Handbook</em> o <em>Practical Reverse Engineering</em>)</li><li>[ ] 5 retos de la vertical en HTB Endgame / Pro Labs / RingZer0</li></ul><h3 id="fase-2-—-inmersion-tecnica-2-8-meses" tabindex="-1">Fase 2 — Inmersión técnica (2-8 meses)</h3><ul><li>[ ] Curso oficial del nicho (OffSec, SANS, INE)</li><li>[ ] 30+ horas en lab dedicado (PG Practice avanzado, exploit.education)</li><li>[ ] Replicar 3 CVEs públicos del último año en el nicho</li><li>[ ] Cert del nicho aprobada (OSWE / OSEP / OSED / etc.)</li></ul><h3 id="fase-3-—-aporte-y-reputacion-8-12-meses" tabindex="-1">Fase 3 — Aporte y reputación (8-12 meses)</h3><ul><li>[ ] Bug bounty en el nicho (HackerOne / Bugcrowd) con al menos 1 hallazgo válido</li><li>[ ] Charla técnica o write-up de 0-day reproducido</li><li>[ ] Contribución a una herramienta open source del nicho</li><li>[ ] Networking en cons (DEF CON, BSides, Ekoparty 🇦🇷, Andsec 🇨🇴)</li></ul><hr><h2 id="💰-salarios-en-colombia-usd-mes" tabindex="-1">💰 Salarios en Colombia (USD/mes)</h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Local 🇨🇴</th><th>Remoto 🌎</th><th>Notas</th></tr></thead><tbody><tr><td>Mid (post-OSCP, 1 cert avanzada)</td><td>$2,500 - $5,000</td><td>$5,000 - $9,000</td><td>OSWE/OSEP es palanca</td></tr><tr><td>Senior (3+ certs avanzadas)</td><td>$5,500 - $10,000</td><td>$9,000 - $16,000</td><td>OSCE3 = top tier LATAM</td></tr><tr><td>Principal / Researcher</td><td>$8,000 - $15,000+</td><td>$14,000 - $25,000+</td><td>0-day discoverers, big tech</td></tr></tbody></table><blockquote><p><strong>Tip:</strong> este nicho <strong>se paga por reputación demostrable</strong> (0-days, CVEs, charlas). El cv pesa menos que el GitHub público.</p></blockquote><hr><h2 id="🔗-conexion-con-otras-ramas" tabindex="-1">🔗 Conexión con otras ramas</h2><ul><li><strong><code>pentester-red-team</code></strong> → tu base previa</li><li><strong><code>malware-analyst</code></strong> → reverse engineering overlap profundo</li><li><strong><code>bug-bounty-hunting</code></strong> → ingreso variable complementario</li><li><strong><code>seguridad-iot-ot</code></strong> → si vas hardware/ICS</li><li><strong><code>cryptographer</code></strong> → si te metes en CTF crypto / TLS exploitation</li><li><strong><code>ai-red-teamer</code></strong> <em>(03)</em> → AI red team es un nicho emergente especializado</li></ul><hr><h2 id="📂-estructura" tabindex="-1">📂 Estructura</h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>penetration-tester-specialized/</span></span>
<span class="line"><span>├── herramientas/    # Custom payloads, evasion templates, exploit POCs</span></span>
<span class="line"><span>├── recursos/        # Papers, blogs (Project Zero, Phrack, Tenable Research)</span></span>
<span class="line"><span>├── laboratorios/    # PG Practice notes, HTB Pro Labs writeups</span></span>
<span class="line"><span>└── casos-uso/       # CVEs reproducidos, 0-days éticos, write-ups técnicos</span></span></code></pre></div><hr><div align="center"><p><strong><a href="./../README">⬅ Volver a Ciberseguridad</a></strong></p></div>`,35)])])}const m=e(d,[["render",o]]);export{h as __pageData,m as default};
